import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardInstallStepLogicValues {
    manualModalOpen: boolean
    sdkInstructionsOpen: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardInstallStepLogicActions {
    setManualModalOpen: (open: boolean) => {
        open: boolean
    }
    setSdkInstructionsOpen: (open: boolean) => {
        open: boolean
    }
}

export type wizardInstallStepLogicType = MakeLogicType<wizardInstallStepLogicValues, wizardInstallStepLogicActions>

export const wizardInstallStepLogic = kea<wizardInstallStepLogicType>([
    path(['scenes', 'onboarding', 'wizardInstallStepLogic']),
    actions({
        setManualModalOpen: (open: boolean) => ({ open }),
        setSdkInstructionsOpen: (open: boolean) => ({ open }),
    }),
    reducers({
        manualModalOpen: [
            false,
            {
                setManualModalOpen: (_, { open }) => open,
            },
        ],
        sdkInstructionsOpen: [
            false,
            {
                setSdkInstructionsOpen: (_, { open }) => open,
            },
        ],
    }),
    listeners({
        setManualModalOpen: ({ open }) => {
            if (open) {
                posthog.capture('wizard manual setup opened', { event_source: 'wizard_ui', location: 'onboarding' })
            }
        },
    }),
])
